from taf.ul.ettf.msg_capture.presenter_packet_conventer import Node, ErrorAttributes, Value, ErrorValue, PacketConverter, ShouldBeOmittedValue
from jinja2 import Environment, FileSystemLoader
from collections import namedtuple
from collections import defaultdict
from html import escape
import random
import string
import os


ACTIVE_TAB_HTML_CLASS = 'active show'
TEMPLATE_DIRECTORY = os.path.dirname(__file__)
Error = namedtuple('Error', ['name', 'id', 'msg', 'field', 'expected', 'actual'])


def get_random_string(length=20):
    return ''.join(random.choice(string.ascii_letters) for _ in range(length))


class PacketWrapper(object):
    def __init__(self, packet, errors, name, timestamp):
        self.packet = packet
        self.timestamp = str(timestamp)
        self.errors = errors
        self.name = name
        self.id = get_random_string()
        self.preloaded = ''

    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self.id == other.id and \
                self.packet == other.packet and \
                self.errors == other.errors and \
                self.name == other.name
        return False


class Expectation(object):
    def __init__(self, name, identifier):
        self.name = name
        self.id = identifier
        self.packet_wrappers = []
        self.has_only_errors = True
        self.preloaded = ''

    def add_packet_wrapper(self, s):
        self.packet_wrappers.append(s)
        if not s.errors:
            self.has_only_errors = False

    def mark_packet_to_preload(self):
        for packet in self.packet_wrappers:
            if not packet.errors:
                packet.preloaded = ACTIVE_TAB_HTML_CLASS
                return
        if self.packet_wrappers:
            self.packet_wrappers[-1].preloaded = ACTIVE_TAB_HTML_CLASS

    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self.packet_wrappers == other.packet_wrappers
        return False


class TemplateTests(object):
    @staticmethod
    def is_red_path(value):
        if isinstance(value, Node):
            return value.has(ErrorAttributes.ERROR) or \
                value.has(ErrorAttributes.MISSING) or \
                value.has(ErrorAttributes.SHOULD_BE_OMITTED) or \
                value.has(ErrorAttributes.UNWANTED)
        return False

    @staticmethod
    def is_single_value(value):
        return isinstance(value, Value)

    @staticmethod
    def is_error(value):
        return isinstance(value, ErrorValue)

    @staticmethod
    def present_when_should_be_omitted(value):
        return isinstance(value, ShouldBeOmittedValue)

    @staticmethod
    def is_missing(key):
        return ErrorAttributes.MISSING in key.attributes


class ComparisonTableGenerator(object):

    def generate_comparison_html(self, history, history_type, name, path=None):
        expectations = []
        for entry_group in self._group_entries(history):
            expectations.append(self._create_expectation(entry_group))
        self._mark_expectation_to_preload(expectations)
        html = self._get_jinja_template().render(expectations=expectations, header=name, history_type=history_type)

        if path:
            with open(path, 'w') as result:
                result.write(html)
        return escape(html, quote=True)

    def _create_expectation(self, entry_group):
        expectation = Expectation(str(entry_group[0].matcher_data.name), get_random_string())
        any_non_empty_comparison_results = False
        for entry in entry_group:
            if entry.comparison_result is not None:
                any_non_empty_comparison_results = True
                if entry.comparison_result.mismatches:
                    for mismatch in entry.comparison_result.mismatches:
                        mismatch.identifier = get_random_string()
                    expectation.add_packet_wrapper(self._create_packet_wrapper(entry))
                else:
                    expectation.add_packet_wrapper(self._create_packet_wrapper(entry))
        expectation.mark_packet_to_preload()
        if not any_non_empty_comparison_results:
            expectation.name = '[!] {}'.format(expectation.name)
        return expectation

    def _create_packet_wrapper(self, entry):
        return PacketWrapper(PacketConverter(entry.packet.data, entry.comparison_result.mismatches).convert(),
                             self._provide_errors_data(entry.comparison_result.mismatches),
                             str(entry.packet.id),
                             entry.packet.data.timestamp)

    def _provide_errors_data(self, mismatches):
        data = []
        for mismatch in mismatches:
            data.append(Error(self._mismatch_field_name(mismatch), mismatch.identifier,
                              mismatch.msg, mismatch.field(), mismatch.expected, mismatch.actual))
        return data

    @staticmethod
    def _get_jinja_template():
        environment = Environment(loader=FileSystemLoader(TEMPLATE_DIRECTORY))
        environment.tests['red_path'] = TemplateTests.is_red_path
        environment.tests['single_value'] = TemplateTests.is_single_value
        environment.tests['error'] = TemplateTests.is_error
        environment.tests['missing'] = TemplateTests.is_missing
        environment.tests['present_when_should_be_omitted'] = TemplateTests.present_when_should_be_omitted
        return environment.get_template('presenter_template.html')

    @staticmethod
    def _group_entries(history):
        grouped_entries = defaultdict(list)
        for entry in history:
            grouped_entries[entry.matcher_data.id].append(entry)
        return list(grouped_entries.values())

    @staticmethod
    def _mismatch_field_name(mismatch):
        return mismatch.field().split('.')[-1] if mismatch.field() else '<i>[root]</i>'

    @staticmethod
    def _mark_expectation_to_preload(expectations):
        for expectation in expectations:
            if expectation.has_only_errors:
                expectation.preloaded = ACTIVE_TAB_HTML_CLASS
                return

        if expectations:
            expectations[0].preloaded = ACTIVE_TAB_HTML_CLASS
